  return res.json()
}

export async function listItems(params: { q?: string; category?:
   string; status?: string; sort?: string; order?: string }): Promise<InventoryItem[]> {
  const paramsUrl = new URLSearchParams(params)
  const paramsUrlStr = paramsUrl.toString()
  const data = await getJson(await fetch(`/api/items?${paramsUrlStr}`))
  return data.items
}

export async function createItem(input: InventoryInput): Promise<InventoryItem> {
  const data = await getJson(await fetch('/api/items', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
