    body: JSON.stringify(input),
  }))
  return data.item
}

export async function deleteItem(id: string): Promise<void> {
  const data = await getJson(await fetch(`/api/items/${id}`, {
    method: 'DELETE',
    headers: { 'Content-Type': 'application/json' },
